def find(a, x):
    for i in range(len(a)):
        if a[i] == x:
            return i
    return -1

def is_sorted(a):
    for i in range(len(a) - 1):
        if a[i] > a[i + 1]:
            return False
    return True

print(find([5, 8, 2, 8], 8), find([5, 8], 3))
print(is_sorted([1, 4, 4, 7]), is_sorted([1, 5, 3]))
